local function _bxor(a,b)
  local r,p=0,1
  while a>0 or b>0 do
    local abit,bbit=a%2,b%2
    if abit~=bbit then r=r+p end
    a=(a-abit)/2; b=(b-bbit)/2; p=p*2
  end
  return r
end
